#!/bin/sh
# Prints the Homebrew formula that installs one version.
#   scripts/formula.sh <version> <tarball> <inputs.json>
# The release carries it as flux-toolchain.rb; sunfmin/homebrew-tap copies
# the newest release's into Formula/flux-toolchain.rb.
set -eu
version=$1
sha=$(shasum -a 256 "$2" | cut -d' ' -f1)
rust=$(jq -er .rust "$3")
flux=$(jq -er .flux "$3")
url="https://github.com/sunfmin/flux-toolchain/releases/download/$version/$(basename "$2")"
cat <<RUBY
# Generated by sunfmin/flux-toolchain (scripts/formula.sh); edits here are overwritten.
class FluxToolchain < Formula
  desc "Flux refinement type checker for Rust, with liquid-fixpoint and z3"
  homepage "https://github.com/sunfmin/flux-toolchain"
  url "$url"
  version "$version"
  sha256 "$sha"
  license all_of: ["MIT", "BSD-3-Clause"]

  depends_on arch: :arm64
  depends_on :macos

  def install
    %w[cargo-flux flux].each do |b|
      inreplace "bin/#{b}", "@@LIBEXEC@@", libexec.to_s
    end
    libexec.install Dir["libexec/*"]
    bin.install "bin/cargo-flux", "bin/flux"
    pkgshare.install "inputs.json"
  end

  def caveats
    <<~EOS
      Flux $(echo "$flux" | cut -c1-10) runs on the Rust $rust toolchain. Its first run adds
      that toolchain through rustup (https://rustup.rs), which must be on the PATH.
      Depend on the flux-rs crate at the same commit:
        flux-rs = { git = "https://github.com/flux-rs/flux.git", rev = "$flux" }
    EOS
  end

  test do
    assert_match "$(echo "$flux" | cut -c1-7)", shell_output("#{bin}/cargo-flux flux --version")
  end
end
RUBY
